<script setup lang="ts">
import {ref,reactive,computed,onMounted,onBeforeUnmount} from 'vue';import {onBeforeRouteLeave} from 'vue-router';import {ElMessage,ElMessageBox} from 'element-plus';import {get,api,message} from '../api';import {useAuth} from '../stores/auth';import Icon from '../components/Icon.vue';
const auth=useAuth(),canWrite=computed(()=>auth.can('plan:maintain')&&auth.user?.businessEntity.type==='PLATFORM'),modeNames:Record<string,string>={ROAD:'公路',RAIL:'铁路',WATER:'水运'},unitNames:Record<string,string>={PER_TON_KM:'元/吨公里',PER_TON:'元/吨',PER_CONTAINER:'元/箱',FIXED:'元/单'};
const rows=ref<any[]>([]),total=ref(0),loading=ref(false),error=ref(''),options=ref<any>({nodes:[],grains:[]}),query=reactive({q:'',mode:'',status:'',page:1,pageSize:10,order:'desc'}),selected=ref<any[]>([]);
const detail=ref<any>(null),priceOpen=ref(false),prices=ref<any[]>([]),priceTotal=ref(0),pricePage=ref(1),priceError=ref(''),nodeOpen=ref(false),nodeRows=ref<any[]>([]),nodeTotal=ref(0),nodeQuery=reactive({q:'',page:1,pageSize:10}),nodeError=ref('');
const editor=ref(false),editKind=ref<'line'|'price'|'node'>('line'),editingId=ref(''),form=reactive<any>({}),formError=ref(''),saving=ref(false);let snapshot='';const date=(v:string)=>new Date(v).toLocaleString('zh-CN',{hour12:false});
async function load(){loading.value=true;error.value='';selected.value=[];try{const data=await get('/transport-lines',Object.fromEntries(Object.entries(query).filter(([,value])=>value!=='')));rows.value=data.items;total.value=data.total;options.value=await get('/plans/options');}catch(e){error.value=message(e);}finally{loading.value=false;}}
function search(){query.page=1;load();}function reset(){Object.assign(query,{q:'',mode:'',status:'',page:1,order:'desc'});load();}
async function loadPrices(){priceError.value='';try{const data=await get('/route-prices',{lineId:detail.value?.id,page:pricePage.value,pageSize:10});prices.value=data.items;priceTotal.value=data.total;}catch(e){priceError.value=message(e);}}
async function showPrices(row?:any){try{detail.value=row?await get('/transport-lines/'+row.id):null;pricePage.value=1;priceOpen.value=true;await loadPrices();}catch(e){ElMessage.error(message(e));}}
async function loadNodes(){nodeError.value='';try{const data=await get('/transport-nodes',nodeQuery);nodeRows.value=data.items;nodeTotal.value=data.total;}catch(e){nodeError.value=message(e);}}
async function showNodes(){nodeOpen.value=true;await loadNodes();}
function edit(kind:'line'|'price'|'node',row?:any){editKind.value=kind;editingId.value=row?.id||'';formError.value='';Object.keys(form).forEach(k=>delete form[k]);const defaults=kind==='line'?{name:'',mode:'ROAD',originId:'',destinationId:'',viaNodes:'',distanceKm:1,durationHours:1,capacity:null,grainIds:[],loadingTypes:['BULK','CONTAINER'],transferMinutes:0,source:'',sourceRef:'',sourceUrl:'',maintainer:'',quality:'DRAFT',enabled:true}:kind==='price'?{lineId:detail.value?.id,grainId:null,unit:detail.value?'PER_TON':'PER_TON_KM',rate:null,validFrom:'',validUntil:'',source:'',maintainer:'',enabled:true}:{name:'',type:'PORT',province:'',city:'',district:'',address:'',lng:null,lat:null,source:'',sourceRef:'',sourceUrl:'',quality:'DRAFT',enabled:true};Object.assign(form,defaults);if(row){for(const key of Object.keys(defaults))if(row[key]!==undefined)form[key]=row[key];if(kind==='line')form.durationHours=Math.round(form.durationHours*100)/100;form.version=row.version;}snapshot=JSON.stringify(form);editor.value=true;}
async function discard(){if(saving.value)return false;if(editor.value&&snapshot!==JSON.stringify(form))try{await ElMessageBox.confirm('尚有未保存的主数据修改。','放弃修改？',{confirmButtonText:'放弃修改',cancelButtonText:'继续编辑'});}catch{return false;}editor.value=false;return true;}
onBeforeRouteLeave(discard);function unload(e:BeforeUnloadEvent){if(editor.value&&snapshot!==JSON.stringify(form)){e.preventDefault();e.returnValue='';}}onMounted(()=>{load();window.addEventListener('beforeunload',unload);});onBeforeUnmount(()=>window.removeEventListener('beforeunload',unload));
async function save(){formError.value='';const kind=editKind.value;if(!form.source?.trim()||!form.maintainer?.trim()&&kind!=='node'){formError.value='请填写数据来源和维护单位';return;}if(kind==='line'&&(!form.name||!form.originId||!form.destinationId||!form.sourceRef||!form.sourceUrl)){formError.value='请完整填写线路、起讫节点与来源依据';return;}if(kind==='price'&&(!form.rate||!form.validFrom||!form.validUntil)){formError.value='请填写价格和有效起止时间';return;}saving.value=true;try{const path=kind==='line'?'/transport-lines':kind==='price'?'/route-prices':'/transport-nodes';const payload={...form};if(!payload.grainId)delete payload.grainId;if(!payload.lineId)delete payload.lineId;if(editingId.value)await api.put(path+'/'+editingId.value,payload,{timeout:60000});else await api.post(path,payload,{timeout:60000});editor.value=false;ElMessage.success('已保存');await load();if(priceOpen.value)await loadPrices();if(nodeOpen.value)await loadNodes();}catch(e){formError.value=message(e);}finally{saving.value=false;}}
const geometryOpen=ref(false),geometryRow=ref<any>(null),geometry=reactive({routeProfile:'VERIFIED_RAIL',source:'',sourceRef:'',text:''}),geometryError=ref('');
function importGeometry(row:any){geometryRow.value=row;Object.assign(geometry,{routeProfile:row.mode==='RAIL'?'VERIFIED_RAIL':'PLANNED_WATER',source:'',sourceRef:'',text:''});geometryError.value='';geometryOpen.value=true;}
async function readGeometry(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>2500000){geometryError.value='文件过大，最多支持50000个坐标点';return;}geometry.text=await file.text();}
async function saveGeometry(){geometryError.value='';let coordinates;try{coordinates=JSON.parse(geometry.text);if(!Array.isArray(coordinates))throw new Error();}catch{geometryError.value='请输入GCJ-02坐标数组，如 [[经度,纬度],…]';return;}saving.value=true;try{await api.post('/transport-lines/'+geometryRow.value.id+'/geometry',{version:geometryRow.value.version,routeProfile:geometry.routeProfile,source:geometry.source,sourceRef:geometry.sourceRef,coordinates});geometryOpen.value=false;ElMessage.success('几何已导入并记录来源');await load();}catch(e){geometryError.value=message(e);}finally{saving.value=false;}}
function exportRows(){const escape=(v:any)=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const csv=[['线路编号','名称','运输方式','起点','终点','里程km','来源','维护单位'],...selected.value.map(r=>[r.businessNo,r.name,modeNames[r.mode],r.origin.name,r.destination.name,r.distanceKm,r.source,r.maintainer])].map(row=>row.map(escape).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='公共线路.csv';a.click();URL.revokeObjectURL(url);}
</script>
<template>
<el-form class="filter-panel" inline @submit.prevent="search"><el-form-item label="关键词"><el-input v-model="query.q" clearable placeholder="线路 / 编号 / 起讫节点" aria-label="线路搜索"/></el-form-item><el-form-item label="方式"><el-select v-model="query.mode" clearable placeholder="全部方式" aria-label="线路方式筛选"><el-option v-for="(label,value) in modeNames" :key="value" :label="label" :value="value"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="query.status" clearable placeholder="全部状态"><el-option label="启用" value="ACTIVE"/><el-option label="停用" value="DISABLED"/></el-select></el-form-item><el-form-item class="filter-actions"><el-button type="primary" plain native-type="submit">搜索</el-button><el-button @click="reset">重置</el-button></el-form-item></el-form>
<section class="table-panel"><div class="list-toolbar"><div><strong>公共线路</strong><span>共 {{total}} 条</span></div><div><el-button @click="showNodes">节点资料</el-button><el-button @click="showPrices()">通用公路参考价</el-button><el-button v-if="canWrite" type="primary" @click="edit('line')"><Icon name="plus" :size="16"/>新增线路</el-button></div></div><div v-if="selected.length" class="bulk-bar">已选择 {{selected.length}} 条 <el-button size="small" @click="exportRows">导出所选</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"><el-button @click="load">重试</el-button></el-alert><el-table v-else :data="rows" v-loading="loading" @selection-change="selected=$event" row-key="id" empty-text="暂无公共线路；平台可维护真实线路，通用公路求解使用有效公路参考价"><el-table-column type="selection" width="44"/><el-table-column label="线路名称 / 编号" min-width="230"><template #default="{row}"><el-button link type="primary" @click="showPrices(row)">{{row.name}}</el-button><small class="cell-note">{{row.businessNo}}</small></template></el-table-column><el-table-column label="起讫节点" min-width="220"><template #default="{row}">{{row.origin.name}} → {{row.destination.name}}<small class="cell-note">{{modeNames[row.mode]}} · {{row.geometry?(row.mode==='ROAD'?'高德道路':row.geometry.routeProfile==='HISTORICAL_AIS'?'历史AIS':'已提供几何'):'缺少路径几何'}}</small></template></el-table-column><el-table-column label="里程 / 时效" width="135"><template #default="{row}">{{row.distanceKm==null?'里程待核验':row.distanceKm.toLocaleString()+' km'}}<small class="cell-note">{{row.durationHours.toFixed(1)}} 小时</small></template></el-table-column><el-table-column label="维护单位" min-width="150"><template #default="{row}">{{row.maintainer}}<small class="cell-note">{{row.source}}</small></template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}"><el-tag size="small" :type="row.enabled&&row.quality==='VERIFIED'?'success':'info'">{{!row.enabled?'已停用':row.quality==='VERIFIED'?'已核验':row.quality==='PUBLIC_REFERENCE'?'公开班线':'待核验'}}</el-tag></template></el-table-column><el-table-column label="操作" fixed="right" :width="canWrite?200:100"><template #default="{row}"><el-button link type="primary" @click="showPrices(row)">详情/价格</el-button><el-button v-if="canWrite&&row.quality!=='PUBLIC_REFERENCE'" link @click="edit('line',row)">编辑</el-button><el-button v-if="canWrite&&row.mode!=='ROAD'" link @click="importGeometry(row)">导入路径</el-button></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="query.page" v-model:page-size="query.pageSize" :total="total" layout="total, sizes, prev, pager, next" @change="load"/></div></section><p class="master-note">参考基础价与承运商报价、成交价分别记录。铁路与水运缺少真实路径时，不绘制推测连线。</p>
<el-drawer v-model="priceOpen" :title="detail?detail.name+' · 线路与价格':'通用公路参考价'" size="min(860px, 100vw)"><template v-if="detail"><el-descriptions :column="2" border><el-descriptions-item label="起讫节点" :span="2">{{detail.origin.name}} → {{detail.destination.name}}</el-descriptions-item><el-descriptions-item label="运输方式">{{modeNames[detail.mode]}}</el-descriptions-item><el-descriptions-item label="里程 / 时长">{{detail.distanceKm==null?'里程待核验':detail.distanceKm+' km'}} / {{detail.durationHours.toFixed(1)}} h</el-descriptions-item><el-descriptions-item label="途经节点">{{detail.viaNodes||'未填写'}}</el-descriptions-item><el-descriptions-item label="容量上限">{{detail.capacity==null?'待确认':Number(detail.capacity).toFixed(1)+' 吨'}}</el-descriptions-item><el-descriptions-item label="衔接等待">{{detail.serviceInfo?.code?'候班与作业时间待确认':detail.transferMinutes+' 分钟'}}</el-descriptions-item><el-descriptions-item label="数据状态">{{detail.quality==='VERIFIED'?'已核验':detail.quality==='PUBLIC_REFERENCE'?'公开班线·班期待确认':'待核验'}} / {{detail.enabled?'启用':'停用'}}</el-descriptions-item><el-descriptions-item label="来源" :span="2">{{detail.source}} · {{detail.sourceRef}} <a :href="detail.sourceUrl" target="_blank" rel="noopener noreferrer">查看来源</a></el-descriptions-item><el-descriptions-item label="路径来源" :span="2">{{detail.geometry?detail.geometry.routeProfile+' · '+date(detail.geometry.queriedAt):'未导入真实几何，求解只展示区段节点'}}</el-descriptions-item></el-descriptions><el-alert v-if="detail.serviceInfo?.code" type="info" :closable="false" :title="detail.serviceInfo.operator+' · '+detail.serviceInfo.frequency+' · '+detail.serviceInfo.transitLabel" :description="'公开资料查阅 '+detail.serviceInfo.checkedAt+'；发布 '+(detail.serviceInfo.publishedAt||'原页未注明')+'。'+detail.serviceInfo.nodeNote"/></template><p v-else class="master-note">公路直接求解及接驳区段使用此价格。具体线路有独立参考价格。价格需提供来源及有效期，成交金额以双方约定为准。</p><div class="drawer-toolbar"><h3>参考价格与有效期</h3><el-button v-if="canWrite" type="primary" @click="edit('price')">新增价格</el-button></div><el-alert v-if="priceError" :title="priceError" type="error" :closable="false"/><el-table :data="prices" empty-text="暂无有效报价；公开班线可作为待报价候选参与比选"><el-table-column label="单价 / 口径" min-width="125"><template #default="{row}"><b>{{row.rate.toLocaleString()}}</b> {{unitNames[row.unit]}}<small class="cell-note">{{row.grainId?options.grains.find((g:any)=>g.id===row.grainId)?.label:'全部粮种'}}</small></template></el-table-column><el-table-column label="有效起止" min-width="180"><template #default="{row}">{{date(row.validFrom)}}<small class="cell-note">至 {{date(row.validUntil)}}</small></template></el-table-column><el-table-column label="来源 / 维护单位" min-width="175"><template #default="{row}">{{row.source}}<small class="cell-note">{{row.maintainer}} · V{{row.version}}</small></template></el-table-column><el-table-column label="状态" width="75"><template #default="{row}">{{row.enabled?'启用':'停用'}}</template></el-table-column><el-table-column v-if="canWrite" label="操作" width="75"><template #default="{row}"><el-button link type="primary" @click="edit('price',row)">编辑</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="pricePage" :total="priceTotal" :page-size="10" layout="total, prev, pager, next" @current-change="loadPrices"/></el-drawer>
<el-drawer v-model="nodeOpen" title="运输节点资料" size="min(950px, 100vw)"><div class="drawer-toolbar"><el-input v-model="nodeQuery.q" placeholder="名称 / 城市" clearable aria-label="节点搜索" @keyup.enter="nodeQuery.page=1;loadNodes()"/><div class="filter-actions"><el-button @click="nodeQuery.page=1;loadNodes()">搜索</el-button><el-button v-if="canWrite" type="primary" @click="edit('node')">新增节点</el-button></div></div><el-alert v-if="nodeError" :title="nodeError" type="error" :closable="false"/><el-table :data="nodeRows"><el-table-column label="节点" min-width="180"><template #default="{row}">{{row.name}}<small class="cell-note">{{row.province}} {{row.city}} {{row.district}}</small></template></el-table-column><el-table-column label="类型 / 坐标" min-width="180"><template #default="{row}">{{({PORT:'港口',RAIL:'铁路站',WAREHOUSE:'粮库/仓库',LOGISTICS:'物流园区'} as any)[row.type]}}<small class="cell-note">{{row.lng}}, {{row.lat}} · GCJ-02</small></template></el-table-column><el-table-column label="来源 / 核验时间" min-width="180"><template #default="{row}">{{row.source}} · {{row.sourceRef}}<small class="cell-note">{{date(row.verifiedAt)}}</small></template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}">{{!row.enabled?'停用':row.quality==='DRAFT'?'待核验':row.quality==='PROVIDER'?'供应商定位':'已核验'}}</template></el-table-column><el-table-column v-if="canWrite" label="操作" width="75"><template #default="{row}"><el-button link type="primary" @click="edit('node',row)">编辑</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="nodeQuery.page" :total="nodeTotal" :page-size="10" layout="total, prev, pager, next" @current-change="loadNodes"/></el-drawer>
<el-drawer v-model="editor" :title="(editingId?'编辑':'新增')+({line:'线路',price:'参考价格',node:'运输节点'} as any)[editKind]" size="min(700px, 100vw)" :close-on-click-modal="false" :before-close="async(done:any)=>{if(await discard())done();}"><el-alert v-if="formError" :title="formError" type="error" :closable="false" class="master-alert"/><el-form label-position="top" :disabled="saving" class="master-form" @submit.prevent="save">
<template v-if="editKind==='line'"><el-form-item label="线路名称" required><el-input v-model="form.name" aria-label="线路名称" maxlength="100"/></el-form-item><div class="master-two"><el-form-item label="运输方式" required><el-select v-model="form.mode" aria-label="运输方式"><el-option v-for="(label,value) in modeNames" :key="value" :label="label" :value="value"/></el-select></el-form-item><el-form-item label="核验状态"><el-select v-model="form.quality"><el-option value="DRAFT" label="待核验"/><el-option value="VERIFIED" label="已核验（依据完整）"/></el-select></el-form-item><el-form-item label="起点节点" required><el-select v-model="form.originId" filterable aria-label="起点节点"><el-option v-for="n in options.nodes" :key="n.id" :label="n.name" :value="n.id"/></el-select></el-form-item><el-form-item label="终点节点" required><el-select v-model="form.destinationId" filterable aria-label="终点节点"><el-option v-for="n in options.nodes" :key="n.id" :label="n.name" :value="n.id"/></el-select></el-form-item><el-form-item label="线路里程（km）"><el-input-number v-model="form.distanceKm" :disabled="form.mode==='ROAD'" :min=".001" :precision="3" controls-position="right"/></el-form-item><el-form-item label="线路时效（小时）"><el-input-number v-model="form.durationHours" :disabled="form.mode==='ROAD'" :min=".01" :precision="2" controls-position="right"/></el-form-item><el-form-item label="承运容量（吨，可选）"><el-input-number v-model="form.capacity" :min=".1" :precision="1" :step=".1" controls-position="right"/></el-form-item><el-form-item label="衔接等待（分钟）"><el-input-number v-model="form.transferMinutes" :min="0" :max="10080" controls-position="right"/></el-form-item></div><el-alert v-if="form.mode==='ROAD'" title="保存时向高德查询真实道路，自动回填里程、时长及几何。" type="info" :closable="false"/><el-form-item label="途经节点"><el-input v-model="form.viaNodes" maxlength="500"/></el-form-item><el-form-item label="适用粮种（不选不限）"><el-select v-model="form.grainIds" multiple><el-option v-for="g in options.grains" :key="g.id" :label="g.label" :value="g.id"/></el-select></el-form-item><el-form-item label="装载形式"><el-checkbox-group v-model="form.loadingTypes"><el-checkbox value="BULK">散装</el-checkbox><el-checkbox value="CONTAINER">集装箱</el-checkbox></el-checkbox-group></el-form-item></template>
<template v-if="editKind==='price'"><div class="master-two"><el-form-item label="适用粮种"><el-select v-model="form.grainId" :disabled="!!editingId" clearable placeholder="全部粮种"><el-option v-for="g in options.grains" :key="g.id" :label="g.label" :value="g.id"/></el-select></el-form-item><el-form-item label="计价单位"><el-select v-model="form.unit" :disabled="!detail" aria-label="计价单位"><el-option v-for="(label,value) in unitNames" :key="value" :label="label" :value="value"/></el-select></el-form-item><el-form-item label="参考单价" required><el-input-number v-model="form.rate" :min=".001" :max="1000000" :precision="3" :step=".001" :controls="false" aria-label="参考单价"/></el-form-item></div><div class="master-two"><el-form-item label="有效开始时间" required><el-date-picker v-model="form.validFrom" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" aria-label="有效开始时间"/></el-form-item><el-form-item label="有效结束时间" required><el-date-picker v-model="form.validUntil" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" aria-label="有效结束时间"/></el-form-item></div><p class="master-note">有效结束时间不包含在区间内。同一线路与粮种的启用价格不允许时间重叠。</p></template>
<template v-if="editKind==='node'"><el-form-item label="节点标准名称" required><el-input v-model="form.name"/></el-form-item><div class="master-two"><el-form-item label="节点类型"><el-select v-model="form.type"><el-option v-for="(label,value) in {PORT:'港口',RAIL:'铁路站',WAREHOUSE:'粮库/仓库',LOGISTICS:'物流园区'}" :key="value" :label="label" :value="value"/></el-select></el-form-item><el-form-item label="数据质量"><el-select v-model="form.quality"><el-option label="待核验" value="DRAFT"/><el-option label="供应商定位" value="PROVIDER"/><el-option label="已核验" value="VERIFIED"/></el-select></el-form-item><el-form-item v-for="(label,key) in {province:'省份',city:'城市',district:'区县'}" :key="key" :label="label" required><el-input v-model="form[key]"/></el-form-item><el-form-item label="地址"><el-input v-model="form.address"/></el-form-item><el-form-item label="GCJ-02 经度" required><el-input-number v-model="form.lng" :min="73" :max="136" :precision="6" :controls="false"/></el-form-item><el-form-item label="GCJ-02 纬度" required><el-input-number v-model="form.lat" :min="3" :max="54" :precision="6" :controls="false"/></el-form-item></div><p class="master-note">坐标修改将使相关线路进入待核验，并解除旧几何关联；已有方案快照保留。</p></template>
<el-form-item label="数据来源" required><el-input v-model="form.source" aria-label="数据来源" maxlength="120" placeholder="供应商 / 文件 / 核验依据"/></el-form-item><template v-if="editKind!=='price'"><el-form-item label="来源记录编号" required><el-input v-model="form.sourceRef" aria-label="来源记录编号" maxlength="160"/></el-form-item><el-form-item label="来源链接（HTTPS）" required><el-input v-model="form.sourceUrl" aria-label="来源链接" placeholder="https://"/></el-form-item></template><el-form-item v-if="editKind!=='node'" label="维护单位" required><el-input v-model="form.maintainer" aria-label="维护单位" maxlength="100"/></el-form-item><el-form-item label="启用"><el-switch v-model="form.enabled"/></el-form-item></el-form><template #footer><el-button @click="discard" :disabled="saving">取消</el-button><el-button type="primary" @click="save" :loading="saving">保存</el-button></template></el-drawer>
<el-dialog v-model="geometryOpen" title="导入真实线路几何" width="min(650px,94vw)" :close-on-click-modal="false" :show-close="!saving"><el-alert v-if="geometryError" :title="geometryError" type="error" :closable="false"/><p class="master-note">{{geometryRow?.name}}。提供GCJ-02点数组与来源依据；线路几何应沿真实铁路或航线，不能使用公路替代。</p><el-form label-position="top" :disabled="saving"><el-form-item label="几何类型"><el-select v-model="geometry.routeProfile"><el-option v-if="geometryRow?.mode==='RAIL'" value="VERIFIED_RAIL" label="已核验铁路"/><template v-else><el-option value="PLANNED_WATER" label="计划航线"/><el-option value="HISTORICAL_AIS" label="历史AIS"/></template></el-select></el-form-item><el-form-item label="来源名称"><el-input v-model="geometry.source"/></el-form-item><el-form-item label="来源依据链接"><el-input v-model="geometry.sourceRef" placeholder="https://"/></el-form-item><el-form-item label="坐标数组 JSON"><input type="file" accept=".json,application/json" @change="readGeometry"/><el-input v-model="geometry.text" type="textarea" :rows="6" placeholder="[[经度,纬度],…]"/></el-form-item></el-form><template #footer><el-button @click="geometryOpen=false" :disabled="saving">取消</el-button><el-button type="primary" @click="saveGeometry" :loading="saving">核验并导入</el-button></template></el-dialog>
</template>
<style scoped>.master-note{font-size:12px;color:#818b97;line-height:1.8;margin:16px 0}.drawer-toolbar{display:flex;gap:12px;align-items:center;justify-content:space-between;margin:20px 0}.drawer-toolbar h3{font-size:14px}.drawer-toolbar>.el-input{max-width:270px}.master-two{display:grid;grid-template-columns:1fr 1fr;gap:0 18px}.master-form :deep(.el-date-editor),.master-form :deep(.el-input-number){width:100%}.master-alert{margin-bottom:16px}.el-pagination{margin-top:16px}a{color:#e52b2f}@media(max-width:650px){.master-two{grid-template-columns:1fr}.list-toolbar{align-items:flex-start;gap:14px;flex-direction:column}.list-toolbar>div:last-child{display:flex;flex-wrap:wrap;gap:8px}.list-toolbar .el-button{margin:0}}</style>


